const request = require('supertest');
const app = require('./app');

describe('POST /users', () => {
  it('should return 400 if name is missing', async () => {
    const res = await request(app)
      .post('/users')
      .send({});
    expect(res.statusCode).toEqual(400);
    expect(res.body.error).toMatch(/name.*required/);
  });

  it('should return 400 if name is not a string', async () => {
    const res = await request(app)
      .post('/users')
      .send({ name: 123 });
    expect(res.statusCode).toEqual(400);
    expect(res.body.error).toMatch(/name.*string/);
  });

  it('should return 400 if name is empty', async () => {
    const res = await request(app)
      .post('/users')
      .send({ name: '' });
    expect(res.statusCode).toEqual(400);
    expect(res.body.error).toMatch(/non-empty/);
  });

  it('should return 201 if name is valid', async () => {
    const res = await request(app)
      .post('/users')
      .send({ name: 'Charlie' });
    expect(res.statusCode).toEqual(201);
    expect(res.body.name).toEqual('Charlie');
  });
});

